CREATE OR REPLACE FUNCTION public.org_member_directory(_org uuid) RETURNS TABLE(id uuid,user_id uuid,role public.app_role,active boolean,full_name text,email text,last_sign_in_at timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_org_role(_org,ARRAY['org_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Only Org Admins can view the directory'; END IF; RETURN QUERY SELECT m.id,m.user_id,m.role,m.active,p.full_name,u.email::text,u.last_sign_in_at FROM public.org_members m JOIN auth.users u ON u.id=m.user_id LEFT JOIN public.profiles p ON p.id=m.user_id WHERE m.org_id=_org ORDER BY p.full_name,u.email; END $$; REVOKE ALL ON FUNCTION public.org_member_directory(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.org_member_directory(uuid) TO authenticated;